class Solution:
    def canAttendMeetings(self, intervals: list[list[int]]) -> bool:
        intervals.sort()                                   # by start time: O(n log n)
        for i in range(1, len(intervals)):                 # neighbours only: O(n)
            if intervals[i][0] < intervals[i - 1][1]:      # starts before the previous one ends
                return False                               # (equal times touch, not overlap)
        return True

